4. The event will stay open to producers who [c][C74848]cleared Season 2, Chapter 1, 1-1 in the Main Story[-][/c]! The event will be displayed in the [c][C74848]main interface[-][/c] during the first week and will be found in [c][C74848]Events[-][/c] after the offer ends.]]
  },
  [160] = {
    rule_type = "SpringAugustBingo",
    rule_title = "Rules",
    rule_desc = [[
