  [194] = {
    rule_type = "LzyBirth92001",
    rule_title = "Rules",
    rule_desc = "The inner voices unlocked, and the key to the past is presented to you.\nYou are now invited to share his exclusive memory.\n\nAfter getting the Birthday Karma [Heartfelt Haven] and preparing a gift for him, join the event [c][C74848]on the day of Victor's birthday[-][/c], and you can unlock the exclusive birthday wishes. He wants to spend this most special day in his life only with you.\n\n◆ Touch Inner Voice to obtain Karma.\n\n1. Use [c][C74848][Key to Hope][-][/c] and [c][C74848][Birthday Card][-][/c] to listen to young Victor's inner voices and get the exclusive birthday gift [Heartbeat Box]. (You can spend 20 Gems for each card)\n\n2. You will also randomly get [c][C74848][Memory Items][-][/c] or one of the following rewards: [Encounter Wish, Gold, Stamina].\n\n3. Memory Items can be used to unlock [c][C74848]Young Victor's Birthday Memories[-][/c].\n\n4. After unlocking all six memories, you can receive Victor's [c][C74848]Birthday Memorial Karma [Victor: Heartfelt Haven][-][/c].\n\n◆ Accumulate touches to obtain multiple rewards.\n\nTouch or Engrave a certain times, and you can receive personal progress rewards such as [Birthday Memorial R Karma, Stamina, Chronicle Seal].\n\n*[c][C74848][Chronicle Seal][-][/c] will be automatically converted into the corresponding number of Ranking Scores and Server Scores when obtained.\n\n◆ Listen to the past and unlock the future.\n\nAfter getting the Birthday Karma [Heartfelt Haven] and preparing a gift for him, you will enter the [c][C74848][Write Birthday Card] stage[-][/c]. Click the arrow on the right side of the screen to write down wishes face to face with him, and you will also receive multiple rewards such as [c][C74848]Chronicle Seal[-][/c].\n\n\n* After 0:00 on the day of Victor's birthday, more Plot Reviews including Young Victor's Birthday Memories will be permanently available on the Birthday Karma [Heartfelt Haven] interface."
  },
  [195] = {
    rule_type = "LzyBirth92001_2",
    rule_title = "Rules",
    rule_desc = "Although we have much time ahead, the precious memories are still worth preserving forever.\nOn this memorable day, flip open the Birthday Card and leave your unfading memories here.\n\n[c][C74848]On the day of Victor's birthday[-][/c], enter the event interface to unlock the exclusive birthday wishes. He wants to spend this most special day in his life only with you.\n\n◆ Write a Birthday Card to redeem multiple rewards.\n\n1. Use [c][C74848][Key to Hope][-][/c] and [c][C74848][Birthday Card][-][/c] to write down your wishes and get the item [c][C74848][Chronicle Seal][-][/c]. (You can spend 20 Gems for each card)\n\n2. In addition to Chronicle Seals, you will also receive [c][C74848][Gift for the Beloved][-][/c], which can be redeemed in the store for various rewards such as Birthday Karma, Suits and Emotion Flowers for the previous years.\n\n*[c][C74848][Chronicle Seal][-][/c] will be automatically converted into the corresponding number of Personal Ranking Scores and Server Scores when obtained.\n\n\n◆ Accumulate wishes to obtain personal rewards.\n\nFinish a certain number of [c][C74848]writing Birthday Card[-][/c] and you can receive rewards such as [c][C74848][Birthday Suits, Birthday Backgrounds and Right Beside You Items][-][/c].\n\n\n* After 0:00 on the day of Victor's birthday, more Plot Reviews including Young Victor's Birthday Memories will be permanently available on the Birthday Karma [Heartfelt Haven] interface."
  },
