  [345] = {
    rule_type = "Birth92010",
    rule_title = "Rules",
    rule_desc = "Vibrance in our eyes, with love as the prize.\nMay the wishes in our hearts one day become the unfeigned reality in our lives.\n\nAfter getting the Birthday Karma [Folded Dusk], preparing a birthday cake, and decorating the room for him, you may join the event [c][C74848]on his birthday[-][/c] to unlock exclusive birthday wishes. He chooses you to spend this special day with.\n\n◆ Throw him a surprise to get Karma.\n\n1. After using the [c][C74848][LED Mini Lights][-][/c] and [c][C74848][Ornaments][-][/c] to prepare the surprise to claim your Bond Wish! (20 Gems can be used in place of each missing Ornament.)\n\n2. You will also gain a random [c][C74848][Memory Item][-][/c] or [Encounter Wish], [Gold], or [Stamina].\n\n3. Memories Items can be used to unlock [c][C74848]Memories for Lucien's previous birthdays[-][/c].\n\n4. Unlocking 6 Memories will grant you Lucien's [c][C74848]special birthday Karma [Lucien: Folded Dusk][-][/c].\n\n◆ Accumulate preparations to unlock multiple rewards.\n\nDecorate or furnish for a certain number of times to get personal progress rewards, including [Birthday R Karma, Stamina, Commitment Points], and more.\n\n*[c][C74848][Commitment Points][-][/c] will be counted towards Personal Ranking Scores and will be automatically converted into the corresponding number of Server Scores when obtained.\n\n◆ Prepare Surprises to celebrate his birthday.\n\nAfter getting the Birthday Karma [Folded Dusk], preparing a birthday cake, and decorating the room for him, you will enter the [c][C74848][Send Blessings] stage[-][/c]. Tap the arrow on the right side of the screen to give him blessings, and you will also receive multiple rewards including [c][C74848]Commitment Points[-][/c].\n\nBirthday cake and decoration materials can be obtained when [c][C74848]preparing the surprise[-][/c]."
  },
  [346] = {
    rule_type = "Birth92010_2",
    rule_title = "Rules",
    rule_desc = "Let the whispers of wishes and the steady gaze in his eyes radiate like the gentle shimmering moonlight.\n\nJoin the event [c][C74848]on his birthday[-][/c] to unlock exclusive birthday wishes. He chooses you to spend this special day with.\n\n\n◆ Send Blessings to unlock multiple rewards.\n\n1. Use [c][C74848][LED Mini Lights][-][/c] and [c][C74848][Ornaments][-][/c] to give blessings and get [c][C74848][Commitment Points][-][/c] (20 Gems can be used in place of each missing Ornament).\n\n*[Commitment Points] will be counted toward Personal Ranking Scores.\n\n2. In addition to Commitment Points, you will also receive [c][C74848][Gentle Whispers][-][/c], which can be redeemed in the shop for various rewards, including the Birthday Karma, Outfits, and various reward items.\n\n*[c][C74848][Commitment Points][-][/c] will be automatically converted into the corresponding Server Scores when obtained.\n\n◆ Accumulate Blessings to obtain personal rewards.\n\n[c][C74848]Send blessings[-][/c] for a certain number of times to earn rewards, including [c][C74848][birthday suits, birthday-exclusive Title Frames, and limited Avatar Frames][-][/c].\n\n\n◆ Celebrate his birthday and get limited items.\n\n*On his birthday, send him cakes in your carefully-arranged room to get [c][C74848]Birthday-Limited Live2D Background[-][/c] and [c][C74848]Journal Ornaments[-][/c] to preserve this moment forever.\n\n*The Journal Ornaments cannot be modified after being obtained.\n\n*A default-style cake journal ornament will be available for Producers who have obtained the Karma without preparing a cake."
  },
  [347] = {
    rule_type = "Birth92010_3",
    rule_title = "Rules",
    rule_desc = [[
[c][C74848]Ranking Rules:[-][/c]

1. Ranking rewards will be awarded based on players' Personal Scores.

*Rewards will be sent by mail within 1-2 working days after the event.


2. The top 100 Producers will also receive a limited title [c][C74848][Fiery in the Fall][-][/c]. If the Server Score goal is reached, the top 3 Producers will also receive [c][C74848]Memory Starburst*2[-][/c] and [c][C74848]Time Coupon*788[-][/c]. The top 4-50 Producers will receive [c][C74848]Time Coupon*788[-][/c].

*The limited title will be sent by mail within 3 working days after the event. Refer to follow-up announcements to stay updated as we produce these rewards.
]]
  },
  [348] = {
    rule_type = "Birth92010_4",
    rule_title = "Rules",
    rule_desc = "Decorate the room for him!\n\n◆ Tap and hold the decors of your choice and [c][C74848]drag them onto the room[-][/c].\n\n◆ Tap on the decors in the room and drag them [c][C74848]to a blank space to remove them[-][/c].\n\n◆ Remember to save the changes after decoration!"
  },
  [349] = {
    rule_type = "Birth92010_5",
    rule_title = "Rules",
    rule_desc = "Make a delicious birthday cake for him.\n\n◆ Tap and hold the ingredients of your choice and [c][C74848]drag them onto the cake[-][/c].\n\n◆ Tap on the ingredients on the cake and drag them [c][C74848]to a blank space to remove them[-][/c].\n\n◆ Remember to save the cake you just made!\n\n*The cake you give him will be turned into a journal ornament after his birthday as a souvenir and will not be available for modification."
  },
  [350] = {
    rule_type = "Birth92011_1",
    rule_title = "Rules",
    rule_desc = "The figure before you softens in the warm glow; behind the gently draped curtains, a serene world of two longing souls emerges.\nToday is a day of perfection without any regrets.\n\nAfter getting the Birthday Karma [Rest of My Life], preparing the Longevity Noodles, and decorating the room for him, you may join the event [c][C74848]on his birthday[-][/c] to unlock exclusive birthday wishes. He chooses you to spend this special day with.\n\n◆ Follow your Heart's Trail and receive a Karma reward.\n\n1. After using the [c][C74848][Blossoming Bouquets]{#i=400059}[-][/c] and [c][C74848][Floating Balloons]{#i=400060}[-][/c] to decorate and garnish in the Heart's Trail, you'll receive Victor's birthday exclusive Mini House gift [Designer Fish Tank]{#i=300208} and [c][C74848]Preparation Progress[-][/c]. (20 Gems can be used in place of each missing balloon).\n\n2. You will also randomly get [c][C74848]Memory Items[-][/c], Encounter Wish{#i=120001}, Gold{#i=1}, or Stamina{#i=41}.\n\n3. Memory Items can be used to unlock [c][C74848]Memories for Victor's previous birthdays[-][/c].\n\n4. Unlocking 6 Memories will grant you Victor's [c][C74848]special Birthday Karma [Victor: Rest of My Life][-][/c].\n\n◆ Accumulate preparations to unlock multiple rewards.\n\nAccumulate [c][C74848]Preparation Progress[-][/c] for a certain amount to get personal progress rewards, including a [c][C74848]birthday R Karma[-][/c], Stamina, Longing Points, and more.\n\n*[c][C74848]Longing Points[-][/c] will be counted towards Personal Ranking Scores and will be automatically converted into the corresponding number of Server Scores when obtained.\n\n◆ Prepare Surprises to celebrate his birthday.\n\nAfter getting the Birthday Karma [Rest of My Life], preparing the birthday Longevity Noodles, and decorating the room for him, you will enter the [c][C74848][Show Affection] stage[-][/c]. Tap the arrow on the right side of the screen to face him and let him know your sincerity. You will receive multiple rewards, including [c][C74848]Longing Points{#i=400058}[-][/c] and [c][C74848]Loving Pts{#i=400062}[-][/c].\n\nBirthday Longevity Noodles and decoration materials can be obtained in [c][C74848]Heart's Trail[-][/c]."
  },
  [351] = {
    rule_type = "Birth92011_2",
    rule_title = "Rules",
    rule_desc = "Paint your wish on the endless starry canvas. May he realize all aspirations in life without fail.\n\nJoin the event [c][C74848]on his birthday[-][/c] to unlock exclusive birthday wishes. He chooses you to spend this special day with.\n\n\n◆ Show him your affection to unlock multiple rewards.\n\n1. Use [c][C74848]Floating Balloons{#i=400060}[-][/c] and [c][C74848]Blossoming Bouquets{#i=400059}[-][/c] to show your affection and get [c][C74848]Longing Points{#i=400058}[-][/c] and [c][C74848]Loving Points{#i=400062}[-][/c]. (20 Gems can be used in place of each missing Balloon).\n\n*[Longing Points] will be counted toward Personal Ranking Scores.\n\n2. In addition to Longing Points, you will also receive [c][C74848][Thoughtful Giftboxes]{#i=400057}[-][/c], which can be redeemed in the shop for various rewards, including the Birthday Karma, Outfits, and various fabulous rewards.\n\n*[c][C74848][Longing Points][-][/c] will be automatically converted into the corresponding Server Scores when obtained.\n\n\n◆ Continue to Show Affection to obtain personal rewards.\n\n[c][C74848]Showing Affection[-][/c] for a certain number of times to earn rewards, including [c][C74848][Birthday Outfits], [Birthday-Exclusive Title Frames], [Birthday-Exclusive Avatar Frames], and more[-][/c].\n\n\n◆ Celebrate his birthday and get limited items.\n\nOn his birthday, send him Longevity Noodles in your carefully-arranged room to get [c][C74848]Birthday-Limited Live2D Background{#i=92011001}[-][/c] and [c][C74848] commemorative Journal pages{#i=400063}[-][/c] to preserve this moment forever.\n\n*You'll be able to make edits to your Journal upon obtaining the commemorative journal page.\n\n*A default-style commemorative Journal page will be available for Producers who have obtained the Karma without preparing the Longevity Noodles."
  },
